from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_header(user_id: str = Header(None)):
    return {"user_id": user_id}

client = TestClient(app)

def test_underscore_header():
    # By default convert_underscores=True. 
    # It should accept 'user-id'
    response = client.get("/", headers={"user-id": "123"})
    print(f"Hyphen header: {response.json()}")
    assert response.json() == {"user_id": "123"}

    # It should NOT accept 'user_id' if convert_underscores=True
    response = client.get("/", headers={"user_id": "456"})
    print(f"Underscore header: {response.json()}")
    # If the issue is that it CURRENTLY accepts it, this assert will fail.
    assert response.json() == {"user_id": None}

def test_underscore_header_disabled():
    # Now we disable convert_underscores
    @app.get("/disabled")
    async def read_header_disabled(user_id: str = Header(None, convert_underscores=False)):
        return {"user_id": user_id}

    # It should accept 'user_id'
    response = client.get("/disabled", headers={"user_id": "789"})
    print(f"Underscore header (disabled): {response.json()}")
    assert response.json() == {"user_id": "789"}

    # It should NOT accept 'user-id'
    response = client.get("/disabled", headers={"user-id": "000"})
    print(f"Hyphen header (disabled): {response.json()}")
    assert response.json() == {"user_id": None}

if __name__ == "__main__":
    try:
        test_underscore_header()
        print("test_underscore_header passed")
    except AssertionError as e:
        print(f"test_underscore_header failed: {e}")

    try:
        test_underscore_header_disabled()
        print("test_underscore_header_disabled passed")
    except AssertionError as e:
        print(f"test_underscore_header_disabled failed: {e}")
EOF
python3 /tmp/repro.py
"}

